<?php use SwimlogStandalone\CalendarView as CV; ?>
<?php foreach($day['items'] as $item): ?>
<?php if(!empty($item['recorded'])): ?><a class="calendar-entry workout-trigger type-<?php echo esc_attr($item['type']); ?><?php echo $item['matched']?' is-matched':''; ?>" draggable="false" data-workout-id="<?php echo esc_attr($item['id']); ?>" aria-haspopup="dialog" aria-expanded="false" href="<?php echo esc_url(CV::url($calendar['date'],$calendar['view']).'&workout='.$item['id']); ?>"><span class="entry-label"><?php if($item['pb']): ?><span class="pb" aria-label="Personal best">★</span> <?php endif; ?><?php echo esc_html($item['label']); ?></span><span class="entry-distance"><?php echo esc_html($item['distance']); ?></span><span class="view-detail-label">View details</span></a>
<?php elseif($item['type']==='plan'): ?><a class="calendar-entry workout-trigger type-plan<?php echo $item['status']==='Completed'?' is-matched':''; ?>" draggable="false"<?php if(!empty($item['move_candidate'])&&current_user_can('swimlog_manage_own_workouts')): ?> data-plan-drag<?php endif; ?> data-plan-id="<?php echo esc_attr($item['id']); ?>" aria-haspopup="dialog" aria-expanded="false" href="<?php echo esc_url(CV::url($calendar['date'],$calendar['view']).'&plan='.$item['id']); ?>"><span class="entry-label"><?php echo esc_html($item['label']); ?></span><span class="entry-distance"><?php echo esc_html($item['distance']); ?></span><span class="view-detail-label"><?php echo esc_html($item['status']); ?> · View plan</span></a>
<?php elseif($item['type']==='event'): ?><a class="calendar-entry workout-trigger type-event" draggable="false" data-event-id="<?php echo esc_attr($item['id']); ?>" aria-haspopup="dialog" aria-expanded="false" href="<?php echo esc_url(CV::url($calendar['date'],$calendar['view']).'&event='.$item['id']); ?>"><span class="entry-label"><?php echo esc_html($item['label']); ?></span><span class="entry-distance"><?php echo esc_html($item['distance']); ?></span><span class="view-detail-label">View event</span></a>
<?php else: ?><details class="calendar-entry type-<?php echo esc_attr($item['type']); ?><?php echo $item['matched']?' is-matched':''; ?>"><summary><span class="entry-label"><?php if($item['pb']): ?><span class="pb" aria-label="Personal best">★</span> <?php endif; ?><?php echo esc_html($item['label']); ?></span><span class="entry-distance"><?php echo esc_html($item['distance']); ?></span></summary><div class="entry-details"><p><?php echo esc_html($item['status']); ?><?php if($item['time']!==null) echo ' · '.esc_html($item['time']); ?></p><?php if($item['location']): ?><p><?php echo esc_html($item['location']); ?></p><?php endif; ?><?php if($item['matched']): ?><p>Matched to a planned swim</p><?php endif; ?><?php if($item['instructions']): ?><p class="instructions"><?php echo esc_html($item['instructions']); ?></p><?php endif; ?></div></details><?php endif; endforeach; ?>
